#!/usr/bin/env bash
set -Euo pipefail
VERSION="1.0.0"
SERVICE="superflash-h2connect.service"
OLD_SERVICE="superflash-xhttp.service"
OLD_NATIVE_SERVICE="superflash-xhttp-native.service"
BASE="/etc/superflash-h2connect"
CONF="$BASE/config"
BIN="/usr/local/bin/superflash-h2connect-server"
UNIT="/etc/systemd/system/$SERVICE"
CERT="/etc/superflash-xhttp/tls/fullchain.pem"
KEY="/etc/superflash-xhttp/tls/key.pem"
LEGACY_CONF="/etc/superflash-xhttp/config"
DEFAULT_PORT=443
DEFAULT_SSH_PORT=22
SHA_AMD64="41b298d658e156c1d04a02d50df709abac66e03906533543eba762ebd36ec03d"
SHA_ARM64="69d1265160f73b0a5a3fa9e7c1ebd18d5b2ed203e77fd150b2269b82614cb216"
B64_AMD64=''
B64_ARM64=''

red='\033[1;31m'; green='\033[1;32m'; cyan='\033[1;36m'; yellow='\033[1;33m'; reset='\033[0m'
need_root(){ [ "${EUID:-$(id -u)}" -eq 0 ] || { echo -e "${red}Ejecuta como root.${reset}"; exit 1; }; }
pause(){ echo; read -r -p "Presiona ENTER para continuar..." _ || true; }
valid_port(){ [[ "${1:-}" =~ ^[0-9]+$ ]] && [ "$1" -ge 1 ] && [ "$1" -le 65535 ]; }

load_conf(){
  H2_PORT=$DEFAULT_PORT; SSH_PORT=$DEFAULT_SSH_PORT; DOMAIN=""
  [ -f "$CONF" ] && . "$CONF"
  if [ -z "$DOMAIN" ] && [ -f "$LEGACY_CONF" ]; then
    # shellcheck disable=SC1090
    . "$LEGACY_CONF" || true
    DOMAIN="${DOMAIN:-}"
    H2_PORT="${H2_PORT:-${XHTTP_PORT:-$DEFAULT_PORT}}"
    SSH_PORT="${SSH_PORT:-$DEFAULT_SSH_PORT}"
  fi
  if [ -z "$DOMAIN" ] && [ -s "$CERT" ]; then
    DOMAIN="$(openssl x509 -in "$CERT" -noout -subject 2>/dev/null | sed -n 's/.*CN *= *\([^,]*\).*/\1/p' | head -1)"
  fi
}
save_conf(){ mkdir -p "$BASE"; printf 'H2_PORT=%q\nSSH_PORT=%q\nDOMAIN=%q\n' "$H2_PORT" "$SSH_PORT" "$DOMAIN" > "$CONF"; chmod 600 "$CONF"; }

install_binary(){
  local arch data expect got
  arch="$(uname -m)"
  case "$arch" in
    x86_64|amd64) data="$B64_AMD64"; expect="$SHA_AMD64" ;;
    aarch64|arm64) data="$B64_ARM64"; expect="$SHA_ARM64" ;;
    *) echo -e "${red}Arquitectura VPS no soportada: $arch${reset}"; return 1;;
  esac
  echo "$data" | base64 -d | gzip -d > "$BIN.tmp"
  got="$(sha256sum "$BIN.tmp" | awk '{print $1}')"
  [ "$got" = "$expect" ] || { rm -f "$BIN.tmp"; echo -e "${red}SHA-256 del motor no coincide.${reset}"; return 1; }
  chmod 0755 "$BIN.tmp"; mv -f "$BIN.tmp" "$BIN"
}

write_unit(){
  cat > "$UNIT" <<EOF
[Unit]
Description=SuperFlash SSH H2 CONNECT native tunnel v$VERSION
After=network-online.target ssh.service sshd.service
Wants=network-online.target

[Service]
Type=simple
ExecStart=$BIN --listen :${H2_PORT} --backend 127.0.0.1:${SSH_PORT} --cert $CERT --key $KEY
Restart=on-failure
RestartSec=1
LimitNOFILE=131072
NoNewPrivileges=true
PrivateTmp=true
ProtectHome=true
ProtectSystem=full

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
}

stop_competing_xhttp(){
  # Solo libera el puerto 443 del experimento XHTTP. BHTTP :80 nunca se toca.
  systemctl stop "$OLD_NATIVE_SERVICE" >/dev/null 2>&1 || true
  systemctl stop "$OLD_SERVICE" >/dev/null 2>&1 || true
}

install_all(){
  need_root; load_conf
  [ -s "$CERT" ] && [ -s "$KEY" ] || { echo -e "${red}No encontré el certificado existente de SuperFlash XHTTP en $CERT / $KEY.${reset}"; echo "Primero conserva/instala el certificado con el manager XHTTP 1.4.0."; return 1; }
  command -v openssl >/dev/null 2>&1 || { echo "Falta openssl"; return 1; }
  install_binary || return 1
  save_conf; write_unit; stop_competing_xhttp
  systemctl enable "$SERVICE" >/dev/null 2>&1 || true
  systemctl restart "$SERVICE"
  sleep .6
  if systemctl is-active --quiet "$SERVICE"; then
    echo -e "${green}✔ SSH_H2 CONNECT v$VERSION ACTIVO :$H2_PORT -> SSH 127.0.0.1:$SSH_PORT${reset}"
    echo "✔ Reutiliza el certificado TLS existente: $DOMAIN"
    echo "✔ BHTTP :80 NO SE TOCÓ"
  else
    echo -e "${red}No inició SSH_H2 CONNECT.${reset}"; journalctl -u "$SERVICE" -n 40 --no-pager || true; return 1
  fi
}

status_all(){
  load_conf
  echo "SUPERFLASH SSH_H2 CONNECT MANAGER v$VERSION"
  echo "Dominio TLS   : ${DOMAIN:-<sin detectar>}"
  echo "H2 CONNECT    : :$H2_PORT -> SSH 127.0.0.1:$SSH_PORT"
  echo "BHTTP :80     : NO SE TOCA"
  echo "Motor SHA256  : $( [ -f "$BIN" ] && sha256sum "$BIN" | awk '{print $1}' || echo '<no instalado>' )"
  systemctl is-active --quiet "$SERVICE" 2>/dev/null && echo "Servicio       : ✔ ON" || echo "Servicio       : ✘ OFF"
  ss -lnt 2>/dev/null | grep -qE "[:.]$H2_PORT[[:space:]]" && echo "Puerto $H2_PORT     : ✔ LISTEN" || echo "Puerto $H2_PORT     : ✘ NO LISTEN"
}

self_test(){
  load_conf
  systemctl is-active --quiet "$SERVICE" || { echo "Servicio SSH_H2 CONNECT apagado"; return 1; }
  [ -n "$DOMAIN" ] || { echo "No pude detectar DOMAIN"; return 1; }
  local out
  out="$(echo | timeout 7 openssl s_client -connect "127.0.0.1:$H2_PORT" -servername "$DOMAIN" -alpn h2 2>/dev/null | tr -d '\000' || true)"
  echo "$out" | grep -q 'ALPN protocol: h2' || { echo -e "${red}✘ ALPN h2 no negociado${reset}"; return 1; }
  echo "$out" | grep -q 'Verify return code: 0' && echo -e "${green}✔ TLS certificado: PASS${reset}" || echo -e "${yellow}△ TLS local: revisa cadena/hostname si openssl no valida por defecto${reset}"
  echo -e "${green}✔ ALPN HTTP/2: h2${reset}"
  echo -e "${green}✔ SSH_H2 CONNECT SERVER ACTIVO${reset}"
  echo "La app LAB10 hará la prueba /health + CONNECT real antes de entregar el bridge SSH."
}

set_port(){ load_conf; read -r -p "Puerto externo H2 CONNECT [$H2_PORT]: " p; p="${p:-$H2_PORT}"; valid_port "$p" || { echo "Puerto inválido"; return 1; }; H2_PORT="$p"; save_conf; write_unit; stop_competing_xhttp; systemctl restart "$SERVICE"; }
set_ssh(){ load_conf; read -r -p "Puerto SSH backend local [$SSH_PORT]: " p; p="${p:-$SSH_PORT}"; valid_port "$p" || { echo "Puerto inválido"; return 1; }; SSH_PORT="$p"; save_conf; write_unit; systemctl restart "$SERVICE"; }
rollback(){ need_root; systemctl disable --now "$SERVICE" >/dev/null 2>&1 || true; if systemctl cat "$OLD_SERVICE" >/dev/null 2>&1; then systemctl enable "$OLD_SERVICE" >/dev/null 2>&1 || true; systemctl restart "$OLD_SERVICE"; echo -e "${green}✔ Restaurado el servidor SSH_XHTTP anterior.${reset}"; else echo -e "${yellow}El servicio anterior $OLD_SERVICE no existe. H2 CONNECT quedó detenido.${reset}"; fi; echo "BHTTP :80 no fue tocado."; }
uninstall(){ need_root; rollback || true; rm -f "$UNIT" "$BIN"; rm -rf "$BASE"; systemctl daemon-reload; echo "SSH_H2 CONNECT eliminado; certificado XHTTP existente conservado."; }

menu(){
  need_root
  while true; do
    clear || true
    echo "======================================================"
    echo " SUPERFLASH SSH_H2 CONNECT MANAGER v$VERSION — DEBUG"
    echo "======================================================"
    status_all || true; echo
    echo "1) Instalar/ACTUALIZAR SSH_H2 CONNECT"
    echo "2) Iniciar/reiniciar SSH_H2 CONNECT"
    echo "3) Estado/diagnóstico"
    echo "4) Autoprueba TLS + ALPN h2"
    echo "5) Ver logs"
    echo "6) Configurar puerto externo (443 por defecto)"
    echo "7) Configurar SSH backend (22 por defecto)"
    echo "8) Detener SSH_H2 CONNECT"
    echo "9) ROLLBACK al servidor SSH_XHTTP anterior"
    echo "10) Desinstalar SOLO SSH_H2 CONNECT"
    echo "0) Salir"
    read -r -p "> " op
    case "$op" in
      1) install_all; pause;;
      2) load_conf; stop_competing_xhttp; write_unit; systemctl restart "$SERVICE"; pause;;
      3) status_all; pause;;
      4) self_test; pause;;
      5) journalctl -u "$SERVICE" -n 120 --no-pager; pause;;
      6) set_port; pause;;
      7) set_ssh; pause;;
      8) systemctl stop "$SERVICE"; pause;;
      9) rollback; pause;;
      10) uninstall; pause;;
      0) exit 0;;
      *) echo "Opción inválida"; sleep 1;;
    esac
  done
}
menu
